@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + AvailableStorageSpace : int
}

class VolunteerDriver {
  + Name : string
  + DaysAvailable : string[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class SecondHandArticle {
  + RFIDTag : string
  + Description : string
  + Category : ItemCategory
}

class Client {
  + Name : string
  + StreetAddress : string
  + NeededCategories : ItemCategory[]
}

class PickupRoute {
  + Date : date
}

class DeliveryService {}

abstract class Employee {
  + FirstName : string
  + LastName : string
}

class H2SEmployee {}

class VolunteerDriver {}

Employee "1" -- "*" PickupVehicle : operates
PickupVehicle "0..*" PickupRoute : follows
VolunteerDriver "1" -- "*" PickupRoute : participatesIn
DistributionCenter "1" -- "*" SecondHandArticle : receives
FoodBank "1" -- "*" SecondHandArticle : receives
H2SEmployee "1" -- "*" SecondHandArticle : examines
H2SEmployee "1" -- "*" Client : communicatesWith
Client "0..*" DeliveryService : uses

enum ItemCategory {
  BabyClothing
  WomenWinterBoots
  Fridge
  Microwave
  // ... other categories
}

@enduml

